from AlgorithmImports import *
from collections import deque
from math import floor


class IndependentSpyAndAppleStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=200)
        self.previous_spy_close = None
        self.previous_spy_sma_50 = None
        self.previous_spy_sma_200 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

        # This supplies values from before the requested backtest start without
        # permitting trades during that history period.
        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data: Slice):
        spy_bar = self._bar_or_none(data, self.symbols["SPY"])
        aapl_bar = self._bar_or_none(data, self.symbols["AAPL"])

        spy_state = None
        if spy_bar is not None:
            spy_state = self._update_spy_state(float(spy_bar.Close))

        if aapl_bar is not None:
            self._update_aapl_state(aapl_bar)

        # State is updated from every available bar, but no rule may be
        # evaluated unless all five subscriptions supplied today's bar.
        if any(self._bar_or_none(data, symbol) is None for symbol in self.symbols.values()):
            self._save_spy_crossing_state(spy_state)
            return
        if self.IsWarmingUp:
            return
        if spy_state is None or not spy_state[0] or not self.aapl_rsi.IsReady:
            self._save_spy_crossing_state(spy_state)
            return

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and spy_state is not None:
            _, close, sma_50, _ = spy_state
            crossed_below_50 = (
                self.previous_spy_close is not None
                and self.previous_spy_sma_50 is not None
                and self.previous_spy_close >= self.previous_spy_sma_50
                and close < sma_50
            )
            if crossed_below_50:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.IsReady:
            if float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

        if self.spy_lot == 0 and spy_state is not None:
            ready, close, _, sma_200 = spy_state
            crossed_above_200 = (
                ready
                and self.previous_spy_close is not None
                and self.previous_spy_sma_200 is not None
                and self.previous_spy_close <= self.previous_spy_sma_200
                and close > sma_200
            )
            if crossed_above_200:
                quantity = floor((0.40 * float(self.Portfolio.TotalPortfolioValue)) / close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if float(self.Portfolio.Cash) >= cash_to_invest:
                quantity = floor(cash_to_invest / float(aapl_bar.Close))
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

        self._save_spy_crossing_state(spy_state)

    def _update_spy_state(self, close):
        self.spy_closes.append(close)
        sma_50 = None
        sma_200 = None
        if len(self.spy_closes) >= 50:
            sma_50 = sum(list(self.spy_closes)[-50:]) / 50
        if len(self.spy_closes) == 200:
            sma_200 = sum(self.spy_closes) / 200

        ready = sma_50 is not None and sma_200 is not None
        state = (ready, close, sma_50, sma_200)

        # Preserve adjacent-day crossing values even when another ticker is
        # absent and therefore suppresses all strategy evaluation today.
        if self.IsWarmingUp:
            self._save_spy_crossing_state(state)
        return state

    def _save_spy_crossing_state(self, state):
        if state is None:
            return
        _, close, sma_50, sma_200 = state
        self.previous_spy_close = close
        self.previous_spy_sma_50 = sma_50
        self.previous_spy_sma_200 = sma_200

    def _update_aapl_state(self, bar):
        close = float(bar.Close)
        if self.previous_aapl_close is None:
            self.aapl_red_streak = 0
        elif close < self.previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0
        self.previous_aapl_close = close
        self.aapl_rsi.Update(bar.EndTime, close)

    @staticmethod
    def _bar_or_none(data, symbol):
        if data.Bars.ContainsKey(symbol):
            return data.Bars[symbol]
        return None

