class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        }

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if all_bars_present:
            spy_close = data.Bars[spy].Close
            aapl_close = data.Bars[aapl].Close

            all_indicators_ready = (
                self.spy_sma_200.IsReady
                and self.spy_sma_50.IsReady
                and self.aapl_rsi_14.IsReady
            )

            if all_indicators_ready:
                spy_sma_200 = self.spy_sma_200.Current.Value
                spy_sma_50 = self.spy_sma_50.Current.Value

                if self.spy_lot > 0:
                    crosses_below_50 = (
                        self.previous_spy_close is not None
                        and self.previous_spy_sma_50 is not None
                        and self.previous_spy_close >= self.previous_spy_sma_50
                        and spy_close < spy_sma_50
                    )
                    if crosses_below_50:
                        self.MarketOrder(spy, -self.spy_lot)
                        self.spy_lot = 0

                if self.aapl_lot > 0 and self.aapl_rsi_14.Current.Value > 60:
                    self.MarketOrder(aapl, -self.aapl_lot)
                    self.aapl_lot = 0

                if self.spy_lot == 0:
                    crosses_above_200 = (
                        self.previous_spy_close is not None
                        and self.previous_spy_sma_200 is not None
                        and self.previous_spy_close <= self.previous_spy_sma_200
                        and spy_close > spy_sma_200
                    )
                    if crosses_above_200:
                        quantity = int(
                            (self.Portfolio.TotalPortfolioValue * 0.40) / spy_close
                        )
                        if quantity > 0:
                            self.MarketOrder(spy, quantity)
                            self.spy_lot = quantity

                if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                    if self.Portfolio.Cash >= 20_000:
                        quantity = int(20_000 // aapl_close)
                        if quantity > 0:
                            self.MarketOrder(aapl, quantity)
                            self.aapl_lot = quantity

                self.previous_spy_sma_200 = spy_sma_200
                self.previous_spy_sma_50 = spy_sma_50

        if data.Bars.ContainsKey(spy):
            self.previous_spy_close = data.Bars[spy].Close
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        if data.Bars.ContainsKey(aapl):
            self.previous_aapl_close = data.Bars[aapl].Close

