class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_closes = deque(maxlen=200)
        self.spy_previous_close = None
        self.spy_previous_sma_50 = None
        self.spy_previous_sma_200 = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker in self.tickers:
            symbol = self.symbols[ticker]
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        spy_bar = bars.get("SPY")
        current_sma_50 = None
        current_sma_200 = None
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))
            if len(self.spy_closes) >= 50:
                current_sma_50 = sum(list(self.spy_closes)[-50:]) / 50.0
            if len(self.spy_closes) == 200:
                current_sma_200 = sum(self.spy_closes) / 200.0

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        complete_day = len(bars) == len(self.tickers)
        indicators_ready = (
            current_sma_50 is not None
            and current_sma_200 is not None
            and self.spy_previous_sma_50 is not None
            and self.spy_previous_sma_200 is not None
            and self.spy_previous_close is not None
            and self.aapl_previous_close is not None
            and self.aapl_rsi.is_ready
        )

        if complete_day and indicators_ready:
            spy_close = float(spy_bar.close)
            aapl_close = float(aapl_bar.close)

            # All sells are evaluated before either strategy's buy.
            spy_crosses_below_50 = (
                self.spy_previous_close >= self.spy_previous_sma_50
                and spy_close < current_sma_50
            )
            if self.spy_lot > 0 and spy_crosses_below_50:
                self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0

            if self.aapl_lot > 0 and self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

            spy_crosses_above_200 = (
                self.spy_previous_close <= self.spy_previous_sma_200
                and spy_close > current_sma_200
            )
            if self.spy_lot == 0 and spy_crosses_above_200:
                quantity = floor(0.40 * float(self.portfolio.total_portfolio_value) / spy_close)
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                cash = float(self.portfolio.cash)
                if cash >= 20_000:
                    quantity = floor(20_000 / aapl_close)
                    if quantity > 0:
                        self.market_order(self.symbols["AAPL"], quantity)
                        self.aapl_lot = quantity

        if spy_bar is not None:
            self.spy_previous_close = float(spy_bar.close)
            if current_sma_50 is not None:
                self.spy_previous_sma_50 = current_sma_50
            if current_sma_200 is not None:
                self.spy_previous_sma_200 = current_sma_200
        if aapl_bar is not None:
            self.aapl_previous_close = float(aapl_bar.close)

