class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, fillForward=False
            ).Symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14)

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

        self.SetWarmUp(200, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_crosses_above_200 = False
        spy_crosses_below_50 = False

        if "SPY" in bars:
            spy_bar = bars["SPY"]
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)

            if (
                self.spy_sma_200.IsReady
                and self.previous_spy_close is not None
                and self.previous_spy_sma_200 is not None
            ):
                spy_crosses_above_200 = (
                    self.previous_spy_close <= self.previous_spy_sma_200
                    and spy_bar.Close > self.spy_sma_200.Current.Value
                )

            if (
                self.spy_sma_50.IsReady
                and self.previous_spy_close is not None
                and self.previous_spy_sma_50 is not None
            ):
                spy_crosses_below_50 = (
                    self.previous_spy_close >= self.previous_spy_sma_50
                    and spy_bar.Close < self.spy_sma_50.Current.Value
                )

            self.previous_spy_close = spy_bar.Close
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close

        if len(bars) != len(self.symbols) or self.IsWarmingUp:
            return

        all_indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
        )
        if not all_indicators_ready:
            return

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Evaluate both independent strategies' sells before either strategy's buy.
        if self.strategy_a_quantity > 0 and spy_crosses_below_50:
            self.MarketOrder(spy, -self.strategy_a_quantity)
            self.strategy_a_quantity = 0

        if (
            self.strategy_b_quantity > 0
            and self.aapl_rsi_14.Current.Value > 60
        ):
            self.MarketOrder(aapl, -self.strategy_b_quantity)
            self.strategy_b_quantity = 0

        if self.strategy_a_quantity == 0 and spy_crosses_above_200:
            quantity = self.CalculateOrderQuantity(spy, 0.40)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.strategy_a_quantity = quantity

        if self.strategy_b_quantity == 0 and self.aapl_red_streak >= 3:
            allocation = 20_000
            if self.Portfolio.Cash >= allocation:
                quantity = int(allocation // bars["AAPL"].Close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.strategy_b_quantity = quantity

