class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma_200 = self.sma(self.spy, 200, Resolution.DAILY)
        self.spy_sma_50 = self.sma(self.spy, 50, Resolution.DAILY)
        self.aapl_rsi_14 = self.rsi(
            self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY
        )

        self.previous_closes = {}
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

        self.set_warm_up(200, Resolution.DAILY)

    def on_data(self, data: Slice):
        bars = data.bars

        if bars.contains_key(self.aapl):
            aapl_close = bars[self.aapl].close
            previous_aapl_close = self.previous_closes.get(self.aapl)
            if previous_aapl_close is not None:
                if aapl_close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        all_bars_present = all(
            bars.contains_key(symbol) for symbol in self.symbols.values()
        )
        indicators_ready = (
            self.spy_sma_200.is_ready
            and self.spy_sma_50.is_ready
            and self.aapl_rsi_14.is_ready
        )
        prior_cross_values_ready = (
            self.spy in self.previous_closes
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
        )

        if (
            all_bars_present
            and indicators_ready
            and prior_cross_values_ready
            and not self.is_warming_up
        ):
            spy_close = bars[self.spy].close
            aapl_close = bars[self.aapl].close
            previous_spy_close = self.previous_closes[self.spy]

            spy_crossed_below_50 = (
                previous_spy_close >= self.previous_spy_sma_50
                and spy_close < self.spy_sma_50.current.value
            )
            if self.spy_lot > 0 and spy_crossed_below_50:
                self.market_order(self.spy, -self.spy_lot)
                self.spy_lot = 0

            if self.aapl_lot > 0 and self.aapl_rsi_14.current.value > 60:
                self.market_order(self.aapl, -self.aapl_lot)
                self.aapl_lot = 0

            spy_crossed_above_200 = (
                previous_spy_close <= self.previous_spy_sma_200
                and spy_close > self.spy_sma_200.current.value
            )
            if self.spy_lot == 0 and spy_crossed_above_200:
                quantity = self.calculate_order_quantity(self.spy, 0.40)
                if quantity > 0:
                    self.market_order(self.spy, quantity)
                    self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                if self.portfolio.cash >= 20_000:
                    quantity = int(20_000 // aapl_close)
                    if quantity > 0:
                        self.market_order(self.aapl, quantity)
                        self.aapl_lot = quantity

        for symbol in self.symbols.values():
            if bars.contains_key(symbol):
                self.previous_closes[symbol] = bars[symbol].close

        if bars.contains_key(self.spy):
            if self.spy_sma_200.is_ready:
                self.previous_spy_sma_200 = self.spy_sma_200.current.value
            if self.spy_sma_50.is_ready:
                self.previous_spy_sma_50 = self.spy_sma_50.current.value

