class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_closes = deque(maxlen=200)
        self.previous_spy_close = None
        self.previous_spy_sma_50 = None
        self.previous_spy_sma_200 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}

    def on_data(self, data: Slice):
        bars = data.bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = bars[spy] if bars.contains_key(spy) else None
        aapl_bar = bars[aapl] if bars.contains_key(aapl) else None

        spy_sma_50 = None
        spy_sma_200 = None
        if spy_bar is not None:
            self.spy_closes.append(Decimal(spy_bar.close))
            if len(self.spy_closes) >= 50:
                spy_sma_50 = sum(list(self.spy_closes)[-50:]) / Decimal(50)
            if len(self.spy_closes) == 200:
                spy_sma_200 = sum(self.spy_closes) / Decimal(200)

        if aapl_bar is not None:
            aapl_close = Decimal(aapl_bar.close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        complete_day = all(
            bars.contains_key(symbol) for symbol in self.symbols.values()
        )

        if complete_day:
            # Sells are evaluated before buys. Each ticker is owned by only its
            # corresponding strategy, so its holdings are that strategy's lot.
            if self.spy_lot > 0 and spy not in self.pending_orders:
                if (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma_50 is not None
                    and spy_sma_50 is not None
                    and self.previous_spy_close >= self.previous_spy_sma_50
                    and Decimal(spy_bar.close) < spy_sma_50
                ):
                    ticket = self.market_order(spy, -self.spy_lot)
                    self.pending_orders[spy] = ticket.order_id

            if self.aapl_lot > 0 and aapl not in self.pending_orders:
                if self.aapl_rsi.is_ready and self.aapl_rsi.current.value > 60:
                    ticket = self.market_order(aapl, -self.aapl_lot)
                    self.pending_orders[aapl] = ticket.order_id

            if self.spy_lot == 0 and spy not in self.pending_orders:
                if (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma_200 is not None
                    and spy_sma_200 is not None
                    and self.previous_spy_close <= self.previous_spy_sma_200
                    and Decimal(spy_bar.close) > spy_sma_200
                ):
                    quantity = self.calculate_order_quantity(spy, 0.40)
                    if quantity > 0:
                        ticket = self.market_order(spy, quantity)
                        self.pending_orders[spy] = ticket.order_id

            if self.aapl_lot == 0 and aapl not in self.pending_orders:
                cash_required = Decimal(20_000)
                if self.aapl_red_streak >= 3 and self.portfolio.cash >= cash_required:
                    quantity = int(cash_required // Decimal(aapl_bar.close))
                    if quantity > 0:
                        ticket = self.market_order(aapl, quantity)
                        self.pending_orders[aapl] = ticket.order_id

        if spy_bar is not None:
            self.previous_spy_close = Decimal(spy_bar.close)
            self.previous_spy_sma_50 = spy_sma_50
            self.previous_spy_sma_200 = spy_sma_200
        if aapl_bar is not None:
            self.previous_aapl_close = Decimal(aapl_bar.close)

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in (OrderStatus.FILLED, OrderStatus.PARTIALLY_FILLED):
            if order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                symbol = order_event.symbol
                if self.pending_orders.get(symbol) == order_event.order_id:
                    del self.pending_orders[symbol]
            return

        symbol = order_event.symbol
        fill_quantity = order_event.fill_quantity
        if symbol == self.symbols["SPY"]:
            self.spy_lot = max(0, self.spy_lot + fill_quantity)
        elif symbol == self.symbols["AAPL"]:
            self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

        if order_event.status == OrderStatus.FILLED:
            if self.pending_orders.get(symbol) == order_event.order_id:
                del self.pending_orders[symbol]

