            self.spy_lot == 0
            and self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_close <= self.previous_spy_sma_200
            and spy_bar.close > self.spy_sma_200.current.value
        ):
            quantity = int(
                (self.portfolio.total_portfolio_value * Decimal("0.40"))
                // spy_bar.close
            )
            if quantity > 0:
                self.market_order(self.spy, quantity)
                self.spy_lot = quantity

        if (
            self.aapl_lot == 0
            and self.aapl_red_streak >= 3
            and self.portfolio.cash >= 20_000
        ):
            quantity = int(Decimal("20000") // aapl_bar.close)
            if quantity > 0:
                self.market_order(self.aapl, quantity)
                self.aapl_lot = quantity

