        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        if aapl_bar is not None and self.previous_aapl_close is not None:
            if aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )
        all_indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
        )

        if all_bars_present and all_indicators_ready:
            self._evaluate_spy(spy_bar)
            self._evaluate_aapl(aapl_bar)

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            self.previous_spy_sma_50 = self.spy_sma_50.Current.Value
            self.previous_spy_indicators_ready = (
                self.spy_sma_200.IsReady and self.spy_sma_50.IsReady
            )

