            self.previous_aapl_close = aapl_bar.Close

    def _evaluate_spy(self, bar: TradeBar):
        if self.spy_lot != 0:
            crosses_below_50 = (
                self.previous_spy_indicators_ready
                and self.previous_spy_close >= self.previous_spy_sma_50
                and bar.Close < self.spy_sma_50.Current.Value
            )
            if crosses_below_50:
                self.MarketOrder(self.spy, -self.spy_lot)
                self.spy_lot = 0

        if self.spy_lot == 0:
            crosses_above_200 = (
                self.previous_spy_indicators_ready
                and self.previous_spy_close <= self.previous_spy_sma_200
                and bar.Close > self.spy_sma_200.Current.Value
            )
            if crosses_above_200:
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.spy_lot = quantity

    def _evaluate_aapl(self, bar: TradeBar):
        if self.aapl_lot != 0 and self.aapl_rsi_14.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
