class ParallelSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.previous_closes = {}
        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_spy_sma_200_ready = False
        self.previous_spy_sma_50_ready = False
        self.aapl_red_streak = 0

        self.spy_lot_open = False
        self.aapl_lot_open = False

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        self._update_market_state(bars)

        if len(bars) != len(self.symbols):
            self._save_spy_cross_state(bars)
            return

        spy = bars["SPY"]
        aapl = bars["AAPL"]

        indicators_ready = (
            self.spy_sma_200.is_ready
            and self.spy_sma_50.is_ready
            and self.aapl_rsi_14.is_ready
        )
        if indicators_ready:
            self._run_spy_strategy(spy)
            self._run_aapl_strategy(aapl)

        self._save_spy_cross_state(bars)

    def _update_market_state(self, bars):
        if "SPY" in bars:
            spy = bars["SPY"]
            self.spy_sma_200.update(spy.end_time, spy.close)
            self.spy_sma_50.update(spy.end_time, spy.close)

        if "AAPL" in bars:
            aapl = bars["AAPL"]
            previous_close = self.previous_closes.get("AAPL")
            if previous_close is None or aapl.close >= previous_close:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak += 1
            self.aapl_rsi_14.update(aapl.end_time, aapl.close)

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.close

    def _save_spy_cross_state(self, bars):
        if "SPY" not in bars:
            return
        self.previous_spy_close = bars["SPY"].close
        self.previous_spy_sma_200 = self.spy_sma_200.current.value
        self.previous_spy_sma_50 = self.spy_sma_50.current.value
        self.previous_spy_sma_200_ready = self.spy_sma_200.is_ready
        self.previous_spy_sma_50_ready = self.spy_sma_50.is_ready

    def _run_spy_strategy(self, bar):
        symbol = self.symbols["SPY"]
        self.spy_lot_open = self.portfolio[symbol].quantity > 0

        if self.spy_lot_open:
            crossed_below_50 = (
                self.previous_spy_close is not None
                and self.previous_spy_sma_50_ready
                and self.previous_spy_close >= self.previous_spy_sma_50
                and bar.close < self.spy_sma_50.current.value
            )
            if crossed_below_50:
                quantity = self.portfolio[symbol].quantity
                self.market_order(symbol, -quantity)
                self.spy_lot_open = False
            return

        crossed_above_200 = (
            self.previous_spy_close is not None
            and self.previous_spy_sma_200_ready
            and self.previous_spy_close <= self.previous_spy_sma_200
            and bar.close > self.spy_sma_200.current.value
        )
        if crossed_above_200:
            quantity = self.calculate_order_quantity(symbol, 0.40)
            if quantity > 0:
                self.market_order(symbol, quantity)
                self.spy_lot_open = True

    def _run_aapl_strategy(self, bar):
        symbol = self.symbols["AAPL"]
        self.aapl_lot_open = self.portfolio[symbol].quantity > 0

        if self.aapl_lot_open:
            if self.aapl_rsi_14.current.value > 60:
                quantity = self.portfolio[symbol].quantity
                self.market_order(symbol, -quantity)
                self.aapl_lot_open = False
            return

        if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
            quantity = int(20_000 // bar.close)
            if quantity > 0:
                self.market_order(symbol, quantity)
                self.aapl_lot_open = True

