                if self.spy_previous_close is not None and self.spy_previous_sma_50 is not None:
                    spy_crossed_below_50 = (
                        self.spy_previous_close >= self.spy_previous_sma_50
                        and spy_close < spy_sma_50
                    )
                self.spy_previous_sma_50 = spy_sma_50

            if len(self.spy_closes) == 200:
                spy_sma_200 = sum(self.spy_closes) / 200.0
                if self.spy_previous_close is not None and self.spy_previous_sma_200 is not None:
                    spy_crossed_above_200 = (
                        self.spy_previous_close <= self.spy_previous_sma_200
