class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes_200 = deque(maxlen=200)
        self.spy_closes_50 = deque(maxlen=50)
        self.spy_previous_close = None
        self.spy_previous_sma_200 = None
        self.spy_previous_sma_50 = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.strategy_a_order = None
        self.strategy_b_order = None

    def OnData(self, data):
        bars = data.Bars
        present = {symbol: bars.ContainsKey(symbol) for symbol in self.symbols}

        spy_crosses_above_200 = False
        spy_crosses_below_50 = False
        if present[self.spy]:
            close = float(bars[self.spy].Close)
            self.spy_closes_200.append(close)
            self.spy_closes_50.append(close)

            sma_200 = None
            sma_50 = None
            if len(self.spy_closes_200) == 200:
                sma_200 = sum(self.spy_closes_200) / 200.0
            if len(self.spy_closes_50) == 50:
                sma_50 = sum(self.spy_closes_50) / 50.0

            if self.spy_previous_close is not None:
                if sma_200 is not None and self.spy_previous_sma_200 is not None:
                    spy_crosses_above_200 = (
                        self.spy_previous_close <= self.spy_previous_sma_200
                        and close > sma_200
                    )
                if sma_50 is not None and self.spy_previous_sma_50 is not None:
                    spy_crosses_below_50 = (
                        self.spy_previous_close >= self.spy_previous_sma_50
                        and close < sma_50
                    )

            self.spy_previous_close = close
            self.spy_previous_sma_200 = sma_200
            self.spy_previous_sma_50 = sma_50

        if present[self.aapl]:
            aapl_bar = bars[self.aapl]
            close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None and close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = close
            self.aapl_rsi.Update(aapl_bar.EndTime, close)

        if not all(present.values()):
            return

        # Each strategy evaluates its exit before its entry.
        if self.strategy_a_shares > 0 and self.strategy_a_order is None:
            if spy_crosses_below_50:
                ticket = self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_order = ticket.OrderId
        elif self.strategy_a_shares == 0 and self.strategy_a_order is None:
            if spy_crosses_above_200:
                close = float(bars[self.spy].Close)
                quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / close)
                if quantity > 0:
                    ticket = self.MarketOrder(self.spy, quantity)
                    self.strategy_a_order = ticket.OrderId

        if self.strategy_b_shares > 0 and self.strategy_b_order is None:
            if self.aapl_rsi.IsReady and float(self.aapl_rsi.Current.Value) > 60.0:
                ticket = self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_order = ticket.OrderId
        elif self.strategy_b_shares == 0 and self.strategy_b_order is None:
            if self.aapl_rsi.IsReady and self.aapl_red_streak >= 3:
                if float(self.Portfolio.Cash) >= 20_000.0:
                    close = float(bars[self.aapl].Close)
                    quantity = floor(20_000.0 / close)
                    if quantity > 0:
                        ticket = self.MarketOrder(self.aapl, quantity)
                        self.strategy_b_order = ticket.OrderId

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId
        if order_id == self.strategy_a_order:
            self.strategy_a_shares += int(order_event.FillQuantity)
