                self.strategy_a_order = None
        elif order_id == self.strategy_b_order:
            self.strategy_b_shares += int(order_event.FillQuantity)
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.strategy_b_order = None

