class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=201)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

    def OnData(self, data):
        has_all_bars = all(symbol in data.Bars for symbol in self.symbols.values())
        spy_bar = data.Bars[self.symbols["SPY"]] if self.symbols["SPY"] in data.Bars else None
        aapl_bar = data.Bars[self.symbols["AAPL"]] if self.symbols["AAPL"] in data.Bars else None

        previous_spy_close = None
        previous_spy_sma_200 = None
        previous_spy_sma_50 = None
        if spy_bar is not None and len(self.spy_closes) >= 200:
            previous_spy_close = self.spy_closes[-1]
            previous_spy_sma_200 = sum(list(self.spy_closes)[-200:]) / 200
        if spy_bar is not None and len(self.spy_closes) >= 50:
            previous_spy_sma_50 = sum(list(self.spy_closes)[-50:]) / 50

        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
        current_spy_sma_200 = None
        current_spy_sma_50 = None
        if spy_bar is not None and len(self.spy_closes) >= 200:
            current_spy_sma_200 = sum(list(self.spy_closes)[-200:]) / 200
        if spy_bar is not None and len(self.spy_closes) >= 50:
            current_spy_sma_50 = sum(list(self.spy_closes)[-50:]) / 50

        if aapl_bar is not None:
            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = float(aapl_bar.Close)
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if not has_all_bars:
            return

        # All exits are evaluated before any entries.
        if (
            self.strategy_a_quantity > 0
            and previous_spy_close is not None
            and previous_spy_sma_50 is not None
            and current_spy_sma_50 is not None
            and previous_spy_close >= previous_spy_sma_50
            and spy_bar.Close < current_spy_sma_50
        ):
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_quantity)
            self.strategy_a_quantity = 0

        if (
            self.strategy_b_quantity > 0
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_quantity)
            self.strategy_b_quantity = 0

        if (
            self.strategy_a_quantity == 0
            and previous_spy_close is not None
            and previous_spy_sma_200 is not None
            and current_spy_sma_200 is not None
            and previous_spy_close <= previous_spy_sma_200
            and spy_bar.Close > current_spy_sma_200
        ):
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_quantity = quantity

        if self.strategy_b_quantity == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = floor(20000 / float(aapl_bar.Close))
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.strategy_b_quantity = quantity

