class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = (self.spy, self.aapl, self.ibm, self.bac, self.aig)

        self.spy_closes = deque(maxlen=200)
        self.previous_spy_close = None
        self.previous_spy_sma_50 = None
        self.previous_spy_sma_200 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_order_pending = False
        self.aapl_order_pending = False

    def on_data(self, data: Slice):
        spy_bar = data.bars.get(self.spy)
        aapl_bar = data.bars.get(self.aapl)

        current_spy_sma_50 = None
        current_spy_sma_200 = None
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))
            if len(self.spy_closes) >= 50:
                current_spy_sma_50 = sum(list(self.spy_closes)[-50:]) / 50.0
            if len(self.spy_closes) == 200:
                current_spy_sma_200 = sum(self.spy_closes) / 200.0

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        complete_slice = all(data.bars.get(symbol) is not None for symbol in self.symbols)
        if complete_slice:
            all_state_ready = (
                current_spy_sma_50 is not None
                and current_spy_sma_200 is not None
                and self.previous_spy_sma_50 is not None
                and self.previous_spy_sma_200 is not None
                and self.previous_spy_close is not None
                and self.previous_aapl_close is not None
                and self.aapl_rsi.is_ready
            )
            if all_state_ready:
                spy_was_flat = int(self.portfolio[self.spy].quantity) == 0
                aapl_was_flat = int(self.portfolio[self.aapl].quantity) == 0
                self._evaluate_sells(spy_bar, current_spy_sma_50)
                self._evaluate_buys(
                    spy_bar,
                    aapl_bar,
                    current_spy_sma_200,
                    spy_was_flat,
                    aapl_was_flat,
                )

        if spy_bar is not None:
            self.previous_spy_close = float(spy_bar.close)
            self.previous_spy_sma_50 = current_spy_sma_50
            self.previous_spy_sma_200 = current_spy_sma_200
        if aapl_bar is not None:
            self.previous_aapl_close = float(aapl_bar.close)

    def _evaluate_sells(self, spy_bar, spy_sma_50):
        spy_shares = int(self.portfolio[self.spy].quantity)
        if not self.spy_order_pending and spy_shares != 0:
            spy_close = float(spy_bar.close)
            crossed_below = (
                self.previous_spy_close >= self.previous_spy_sma_50
                and spy_close < spy_sma_50
            )
            if crossed_below:
                self.spy_order_pending = True
                self.market_order(self.spy, -spy_shares, tag="Strategy A: SPY crossed below SMA50")

        aapl_shares = int(self.portfolio[self.aapl].quantity)
        if not self.aapl_order_pending and aapl_shares != 0:
            if float(self.aapl_rsi.current.value) > 60.0:
                self.aapl_order_pending = True
                self.market_order(self.aapl, -aapl_shares, tag="Strategy B: AAPL RSI above 60")

    def _evaluate_buys(
        self, spy_bar, aapl_bar, spy_sma_200, spy_was_flat, aapl_was_flat
    ):
        spy_close = float(spy_bar.close)
        if not self.spy_order_pending and spy_was_flat:
            crossed_above = (
                self.previous_spy_close <= self.previous_spy_sma_200
                and spy_close > spy_sma_200
            )
            if crossed_above:
                quantity = floor(0.40 * float(self.portfolio.total_portfolio_value) / spy_close)
                if quantity > 0:
                    self.spy_order_pending = True
                    self.market_order(self.spy, quantity, tag="Strategy A: SPY crossed above SMA200")

        if not self.aapl_order_pending and aapl_was_flat:
            cash_to_invest = 20_000.0
            available_cash = float(self.portfolio.cash_book["USD"].amount)
            if self.aapl_red_streak >= 3 and available_cash >= cash_to_invest:
                quantity = floor(cash_to_invest / float(aapl_bar.close))
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.market_order(self.aapl, quantity, tag="Strategy B: AAPL red for 3 days")

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID):
            return
        if order_event.symbol == self.spy:
            self.spy_order_pending = False
        elif order_event.symbol == self.aapl:
            self.aapl_order_pending = False

