class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = self.SMA(self.symbols["SPY"], 200, Resolution.Daily)
        self.spy_sma_50 = self.SMA(self.symbols["SPY"], 50, Resolution.Daily)
        self.aapl_rsi_14 = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.spy_previous_close = None
        self.spy_previous_sma_200 = None
        self.spy_previous_sma_50 = None
        self.aapl_closes = deque(maxlen=4)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        # One extra observation is needed to compare today's fully formed
        # 200-day SMA with yesterday's fully formed value.
        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(aapl):
            self.aapl_closes.append(float(data.Bars[aapl].Close))

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if not self.IsWarmingUp and all_bars_present and self._all_state_ready():
            self._evaluate_strategy_a(data.Bars[spy])
            self._evaluate_strategy_b(data.Bars[aapl])

        # Crossing state follows SPY's own trading bars even when another
        # subscription is missing and therefore prevents rule evaluation.
        if data.Bars.ContainsKey(spy):
            self.spy_previous_close = float(data.Bars[spy].Close)
            if self.spy_sma_200.IsReady:
                self.spy_previous_sma_200 = float(self.spy_sma_200.Current.Value)
            if self.spy_sma_50.IsReady:
                self.spy_previous_sma_50 = float(self.spy_sma_50.Current.Value)

    def _all_state_ready(self):
        return (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and self.spy_previous_close is not None
            and self.spy_previous_sma_200 is not None
            and self.spy_previous_sma_50 is not None
            and len(self.aapl_closes) == 4
        )

    def _evaluate_strategy_a(self, bar):
        close = float(bar.Close)
        sma_200 = float(self.spy_sma_200.Current.Value)
        sma_50 = float(self.spy_sma_50.Current.Value)

        if self.strategy_a_shares > 0:
            crossed_below_50 = (
                self.spy_previous_close >= self.spy_previous_sma_50
                and close < sma_50
            )
            if crossed_below_50:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_a_shares == 0:
            crossed_above_200 = (
                self.spy_previous_close <= self.spy_previous_sma_200
                and close > sma_200
            )
            if crossed_above_200:
                quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.strategy_a_shares = quantity

    def _evaluate_strategy_b(self, bar):
        if self.strategy_b_shares > 0:
            if float(self.aapl_rsi_14.Current.Value) > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_b_shares == 0:
            closes = list(self.aapl_closes)
            red_for_three_days = (
                closes[-3] < closes[-4]
                and closes[-2] < closes[-3]
                and closes[-1] < closes[-2]
            )
            if red_for_three_days and self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / float(bar.Close))
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

