                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close

        if self.IsWarmingUp:
            return

        if any(
            not data.Bars.ContainsKey(symbol)
            for symbol in self.symbols.values()
        ):
            return

        spy_close = float(data.Bars[spy].Close)
        aapl_close = float(data.Bars[aapl].Close)

        # Strategy A: evaluate its sell before its buy.
        if len(self.spy_closes) >= 201:
            closes = list(self.spy_closes)
            previous_close = closes[-2]
            previous_sma_200 = sum(closes[:-1]) / 200.0
            current_sma_200 = sum(closes[1:]) / 200.0
            previous_sma_50 = sum(closes[-51:-1]) / 50.0
            current_sma_50 = sum(closes[-50:]) / 50.0

            if self.strategy_a_shares > 0:
                crossed_below_50 = (
                    previous_close >= previous_sma_50
                    and spy_close < current_sma_50
                )
                if crossed_below_50:
                    self.MarketOrder(spy, -self.strategy_a_shares)
                    self.strategy_a_shares = 0
            else:
                crossed_above_200 = (
                    previous_close <= previous_sma_200
                    and spy_close > current_sma_200
                )
                if crossed_above_200:
                    quantity = self.CalculateOrderQuantity(spy, 0.40)
                    if quantity > 0:
                        self.MarketOrder(spy, quantity)
                        self.strategy_a_shares = quantity

        # Strategy B: evaluate its sell before its buy.
        if self.aapl_rsi.IsReady:
            if self.strategy_b_shares > 0:
                if float(self.aapl_rsi.Current.Value) > 60.0:
                    self.MarketOrder(aapl, -self.strategy_b_shares)
                    self.strategy_b_shares = 0
            elif self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
                quantity = floor(20_000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.strategy_b_shares = quantity

