class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = self.SMA(self.symbols["SPY"], 200, Resolution.Daily)
        self.spy_sma_50 = self.SMA(self.symbols["SPY"], 50, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.SetWarmUp(200, Resolution.Daily)

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(aapl):
            aapl_close = data.Bars[aapl].Close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if all_bars_present and not self.IsWarmingUp:
            indicators_ready = (
                self.spy_sma_200.IsReady
                and self.spy_sma_50.IsReady
                and self.aapl_rsi.IsReady
                and self.previous_spy_close is not None
                and self.previous_spy_sma_200 is not None
                and self.previous_spy_sma_50 is not None
                and self.previous_aapl_close is not None
            )
            if indicators_ready:
                self._evaluate_strategy_a(data.Bars[spy])
                self._evaluate_strategy_b(data.Bars[aapl])

        if data.Bars.ContainsKey(spy):
            self.previous_spy_close = data.Bars[spy].Close
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

    def _evaluate_strategy_a(self, spy_bar):
        close = spy_bar.Close
        sma_200 = self.spy_sma_200.Current.Value
        sma_50 = self.spy_sma_50.Current.Value

        if self.strategy_a_shares > 0:
            crossed_below_50 = (
                self.previous_spy_close >= self.previous_spy_sma_50
                and close < sma_50
            )
            if crossed_below_50:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
            return

        crossed_above_200 = (
            self.previous_spy_close <= self.previous_spy_sma_200
            and close > sma_200
        )
        if crossed_above_200:
            shares = floor(0.40 * self.Portfolio.TotalPortfolioValue / close)
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

    def _evaluate_strategy_b(self, aapl_bar):
        if self.strategy_b_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
            return

        cash_to_invest = 20_000
        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= cash_to_invest:
            shares = floor(cash_to_invest / aapl_bar.Close)
            if shares > 0:
                self.MarketOrder(self.symbols["AAPL"], shares)
                self.strategy_b_shares = shares

