class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_close = {symbol: None for symbol in self.symbols.values()}
        self.spy_previous_sma_200 = None
        self.spy_previous_sma_50 = None
        self.spy_cross_previous_close = None
        self.aapl_red_streak = 0

        # Quantities are private strategy lots rather than aggregate holdings.
        self.spy_lot = 0
        self.aapl_lot = 0

        # This supplies pre-start observations, but OnData still refuses to trade
        # until every rule input reports that it is fully formed.
        self.SetWarmUp(200, Resolution.Daily)

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Indicators and market-state counters advance whenever their own bar is
        # present, even when another subscription is absent and trading is skipped.
        if spy in data.Bars:
            bar = data.Bars[spy]
            self.spy_cross_previous_close = self.previous_close[spy]
            if self.spy_sma_200.IsReady:
                self.spy_previous_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.spy_previous_sma_50 = self.spy_sma_50.Current.Value
            self.spy_sma_200.Update(bar.EndTime, bar.Close)
            self.spy_sma_50.Update(bar.EndTime, bar.Close)
            self.previous_close[spy] = bar.Close

        if aapl in data.Bars:
            bar = data.Bars[aapl]
            prior_close = self.previous_close[aapl]
            if prior_close is None or bar.Close >= prior_close:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak += 1
            self.aapl_rsi_14.Update(bar.EndTime, bar.Close)
            self.previous_close[aapl] = bar.Close

        # Retain previous closes for the other subscriptions as continuous market
        # state, even though the two strategies do not otherwise use them.
        for ticker in ["IBM", "BAC", "AIG"]:
            symbol = self.symbols[ticker]
            if symbol in data.Bars:
                self.previous_close[symbol] = data.Bars[symbol].Close

        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return
        if self.IsWarmingUp:
            return
        if not (self.spy_sma_200.IsReady and self.spy_sma_50.IsReady and self.aapl_rsi_14.IsReady):
            return
        if self.spy_previous_sma_200 is None or self.spy_previous_sma_50 is None:
            return

        spy_close = data.Bars[spy].Close
        spy_prior_close = self.spy_cross_previous_close

        # Sells are evaluated before buys, independently for each strategy lot.
        if self.spy_lot > 0 and spy_prior_close is not None:
            crossed_below_50 = (
                spy_prior_close >= self.spy_previous_sma_50
                and spy_close < self.spy_sma_50.Current.Value
            )
            if crossed_below_50:
                self.MarketOrder(spy, -self.spy_lot)
                self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi_14.Current.Value > 60:
            self.MarketOrder(aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_prior_close is not None:
            crossed_above_200 = (
                spy_prior_close <= self.spy_previous_sma_200
                and spy_close > self.spy_sma_200.Current.Value
            )
            if crossed_above_200:
                quantity = self.CalculateOrderQuantity(spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(spy, quantity)
                    self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            allocation = 20_000
            if self.Portfolio.Cash >= allocation:
                quantity = int(allocation // data.Bars[aapl].Close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.aapl_lot = quantity

