class IndependentSpyAndAppleAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False
        self.order_strategies = {}

    def OnData(self, data: Slice):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        previous_spy_close = self.previous_spy_close
        previous_spy_sma_200 = self.previous_spy_sma_200
        previous_spy_sma_50 = self.previous_spy_sma_50

        if spy_bar is not None:
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)
            self.previous_spy_close = spy_bar.Close
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        if aapl_bar is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.previous_aapl_close = aapl_bar.Close

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and previous_spy_close is not None
            and previous_spy_sma_200 is not None
            and previous_spy_sma_50 is not None
        )
        if not indicators_ready:
            return

        # Sells are evaluated before buys for both independent strategy lots.
        if self.spy_lot > 0 and not self.spy_order_pending:
            crossed_below_50 = (
                previous_spy_close >= previous_spy_sma_50
                and spy_bar.Close < self.spy_sma_50.Current.Value
            )
            if crossed_below_50:
                self._submit_order(self.spy, -self.spy_lot, "spy")

        if self.aapl_lot > 0 and not self.aapl_order_pending:
            if self.aapl_rsi_14.Current.Value > 60:
                self._submit_order(self.aapl, -self.aapl_lot, "aapl")

        if self.spy_lot == 0 and not self.spy_order_pending:
            crossed_above_200 = (
                previous_spy_close <= previous_spy_sma_200
                and spy_bar.Close > self.spy_sma_200.Current.Value
            )
            if crossed_above_200:
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self._submit_order(self.spy, quantity, "spy")

        if self.aapl_lot == 0 and not self.aapl_order_pending:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                quantity = math.floor(20_000 / float(aapl_bar.Close))
                if quantity > 0:
                    self._submit_order(self.aapl, quantity, "aapl")

    def _submit_order(self, symbol, quantity, strategy):
        ticket = self.MarketOrder(symbol, quantity)
        self.order_strategies[ticket.OrderId] = strategy
        if strategy == "spy":
            self.spy_order_pending = True
        else:
            self.aapl_order_pending = True

    def OnOrderEvent(self, order_event: OrderEvent):
        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
            filled = int(order_event.FillQuantity)
            if strategy == "spy":
                self.spy_lot = max(0, self.spy_lot + filled)
            else:
                self.aapl_lot = max(0, self.aapl_lot + filled)

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if strategy == "spy":
                self.spy_order_pending = False
            else:
                self.aapl_order_pending = False
            self.order_strategies.pop(order_event.OrderId, None)

