class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        }

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]
        self.spy_sma_200 = self.SMA(spy, 200, Resolution.Daily)
        self.spy_sma_50 = self.SMA(spy, 50, Resolution.Daily)
        self.aapl_rsi_14 = self.RSI(
            aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.aapl_closes = deque(maxlen=4)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Keep private-lot share counts aligned with split-adjusted holdings.
        if self.strategy_a_shares > 0 and self.Portfolio[spy].Quantity > 0:
            self.strategy_a_shares = int(self.Portfolio[spy].Quantity)
        if self.strategy_b_shares > 0 and self.Portfolio[aapl].Quantity > 0:
            self.strategy_b_shares = int(self.Portfolio[aapl].Quantity)

        if spy in data.Bars:
            spy_close = data.Bars[spy].Close
            spy_200 = (
                self.spy_sma_200.Current.Value if self.spy_sma_200.IsReady else None
            )
            spy_50 = self.spy_sma_50.Current.Value if self.spy_sma_50.IsReady else None
        else:
            spy_close = None
            spy_200 = None
            spy_50 = None

        if aapl in data.Bars:
            self.aapl_closes.append(data.Bars[aapl].Close)

        complete_slice = all(symbol in data.Bars for symbol in self.symbols.values())

        if complete_slice:
            # All sells are evaluated before either independent strategy can buy.
            if self.strategy_a_shares > 0 and self._spy_crosses_below_50(
                spy_close, spy_50
            ):
                self.MarketOrder(spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if (
                self.strategy_b_shares > 0
                and self.aapl_rsi_14.IsReady
                and self.aapl_rsi_14.Current.Value > 60
            ):
                self.MarketOrder(aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if (
                self.strategy_a_shares == 0
                and self.spy_sma_200.IsReady
                and self.spy_sma_50.IsReady
                and self._spy_crosses_above_200(spy_close, spy_200)
            ):
                shares = floor(0.40 * self.Portfolio.TotalPortfolioValue / spy_close)
                if shares > 0:
                    self.MarketOrder(spy, shares)
                    self.strategy_a_shares = shares

            if (
                self.strategy_b_shares == 0
                and self.aapl_rsi_14.IsReady
                and self._aapl_red_for_at_least_three_days()
                and self.Portfolio.Cash >= 20_000
            ):
                shares = floor(20_000 / data.Bars[aapl].Close)
                if shares > 0:
                    self.MarketOrder(aapl, shares)
                    self.strategy_b_shares = shares

        # Preserve the actual preceding SPY trading day's values even when another
        # subscription was absent and trading-rule evaluation was skipped.
        if spy_close is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_sma_200 = spy_200
            self.previous_spy_sma_50 = spy_50

    def _spy_crosses_above_200(self, close, sma):
        return (
            self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_close <= self.previous_spy_sma_200
            and close > sma
        )

    def _spy_crosses_below_50(self, close, sma):
        return (
            sma is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma_50 is not None
            and self.previous_spy_close >= self.previous_spy_sma_50
            and close < sma
        )

    def _aapl_red_for_at_least_three_days(self):
        return len(self.aapl_closes) == 4 and all(
            self.aapl_closes[index] < self.aapl_closes[index - 1]
            for index in range(1, 4)
        )
